async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  message: ListSessionsMessage,
  sessionStore?: SessionStore
): Promise<void> {
  if (typeof sessionStore?.listFor !== 'function') {
    sendJson(ws, {type: 'session_list', sessions: []});
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, {limit: message.limit, before: message.before});
    const sessions = summaries.map(s => ({
      sessionId: s.sessionId,
      createdAt: s.createdAt instanceof Date ? s.createdAt.toISOString() : (s.createdAt as string),
      updatedAt: s.updatedAt instanceof Date ? s.updatedAt.toISOString() : (s.updatedAt as string),
      entryCount: s.entryCount,
    }));
    sendJson(ws, {type: 'session_list', sessions});
  } catch (err) {
    const errorMessage = err instanceof Error ? err.message : 'Unknown error';
    log.error('ws', 'listFor failed', {userId: session.userId, error: errorMessage});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list sessions');
  }
}

function handlePing(ws: WebSocket, timestamp: number): void {
  ws.send(JSON.stringify({type: 'pong', timestamp}));
